from lib import *
S = SS('x87')
steps = [
    step("容器里的 UserRepo 到底是什么。repo.getClass() 是 jdk.proxy2.$Proxy107,AopUtils.isJdkDynamicProxy 为 true,也就是一个 JDK 动态代理;它实现的接口是 UserRepo、Repository、TransactionalProxy、Advised、DecoratingProxy;代理背后的目标对象(Advised.getTargetSource().getTarget())是 org.springframework.data.jpa.repository.support.SimpleJpaRepository。Bean 定义的类不是 UserRepo,而是 JpaRepositoryFactoryBean——容器里 UserRepo 类型的 Bean 只有 1 个,名字是 userRepo,它的工厂 Bean 是 &userRepo。所以你写的接口根本没有实现类,运行时 Spring Data 用工厂 Bean 生成了一个代理,把一部分调用交给 SimpleJpaRepository。", t=tl(S(1)), mark=lidx(S(1), 'repo.getClass()', 'BeanDefinition 的类'), done=lidx(S(1), '实现的接口', '代理的目标对象', '容器里 UserRepo'), b=bars([['代理实现的接口个数(数出来的)', 5, '5'], ['容器里 UserRepo 类型的 Bean 个数', 1, '1'], ['你自己写的实现类个数', 0, '0']], 5, done=[0, 1], mark=[2]), kv=KV([['Bean 的真实类型', 'jdk.proxy2.$Proxy107(JDK 动态代理)'], ['目标对象', 'SimpleJpaRepository'], ['Bean 定义', 'JpaRepositoryFactoryBean(工厂 Bean &userRepo)'], ['你的接口', '没有实现类,运行时生成代理']], ['Bean 的真实类型'])),
    step("代理上挂了 7 个拦截器(Advised.getAdvisors,按顺序):CrudMethodMetadataPostProcessor 的 CrudMethodMetadataPopulatingMethodInterceptor、PersistenceExceptionTranslationInterceptor、TransactionInterceptor、DefaultMethodInvokingMethodInterceptor、QueryExecutorMethodInterceptor、RepositoryFactorySupport 的 ImplementationMethodExecutionInterceptor,最后又是一个 PersistenceExceptionTranslationInterceptor(异常转换出现了 2 次)。事务拦截器排在第 3 位,所以每个方法调用先过它,再分派到「查询方法」或「基础实现」。", t=tl(S(2)), mark=lidx(S(2), 'TransactionInterceptor', 'QueryExecutorMethodInterceptor', 'ImplementationMethodExecutionInterceptor'), done=lidx(S(2), 'CrudMethodMetadataPopulatingMethodInterceptor', 'DefaultMethodInvokingMethodInterceptor'), b=bars([['拦截器总个数', 7, '7'], ['事务拦截器的位置', 3, '第 3 个'], ['PersistenceExceptionTranslationInterceptor 出现次数', 2, '2']], 7, done=[0], mark=[1, 2]), kv=KV([['第 3 位', 'TransactionInterceptor'], ['分派', 'QueryExecutorMethodInterceptor 与 ImplementationMethodExecutionInterceptor'], ['default 方法', 'DefaultMethodInvokingMethodInterceptor'], ['异常转换', '出现了 2 次']], ['第 3 位'])),
    step("不同方法在 SQL 发出的那一瞬间,事务状态和调用栈。findAll()、findById(1L)、count():事务激活=true、只读=true;调用栈从外到里是 $Proxy107.findAll → JdkDynamicAopProxy.invoke → TransactionInterceptor.invoke → DefaultMethodInvokingMethodInterceptor → QueryExecutorMethodInterceptor → ImplementationMethodExecutionInterceptor → SimpleJpaRepository.findAll。save(new User):事务激活=true、只读=false(insert),同样走 SimpleJpaRepository.save。派生查询 findByName(\"a\"):事务激活=false、只读=false——栈里是 $Proxy107.findByName → … → QueryExecutorMethodInterceptor.invoke → AbstractJpaQuery.execute,没有经过 SimpleJpaRepository,SQL 是在没有事务的情况下执行的。自定义片段 custom():没有发出 SQL,方法体里的事务状态是 事务激活=false。接口里的 default 方法 hello() 里调 count():返回 default 方法:3,栈底是 $Proxy107.hello,中间又调到 $Proxy107.count,所以 count 部分有事务、只读。也就是说「事务」是 SimpleJpaRepository 这个类上的 @Transactional 带来的,只覆盖它自己的方法,派生查询和你写的自定义实现需要自己加 @Transactional。", t=tl(S(3)), mark=lidx(S(3), 'findByName', 'custom()'), done=lidx(S(3), 'findAll()', 'findById(1L)', 'save(new User)', 'count()', 'hello()'), b=bars([['findAll:事务激活(1=是)', 1, '是,只读'], ['save:事务激活', 1, '是,可写'], ['findByName(派生查询):事务激活', 0, '否'], ['custom():事务激活', 0, '否'], ['count():事务激活', 1, '是,只读']], 1, done=[0, 1, 4], mark=[2, 3]), kv=KV([['SimpleJpaRepository 的方法', '读:事务 + 只读;写(save):事务 + 可写'], ['派生查询', '没有事务'], ['自定义片段', '没有事务'], ['default 方法', '里面调的 count() 仍走代理,所以有事务']], ['派生查询'])),
    step("补一个对照:在 Repository 之外、没有任何 @Transactional 的调用方里,事务状态是 事务激活=false、只读=false。所以前面看到的事务激活=true,全部是 Repository 代理自己开启并在调用结束时提交的;调用方想让几次 Repository 调用处在同一个事务里,要自己在 Service 上加 @Transactional,否则每次调用各开各的事务(派生查询则根本没有事务)。", t=tl(S(4)), mark=lidx(S(4), '外面(调用方)当前'), done=[], b=bars([['调用方当前的事务激活(1=是)', 0, '否'], ['Repository 方法内部的事务激活(以 findAll 为例)', 1, '是']], 1, mark=[0], done=[1]), kv=KV([['调用方', '没有事务'], ['Repository 内部', '读写方法各自开事务'], ['要同一个事务', 'Service 上加 @Transactional'], ['派生查询', '没有事务,同样要靠外层事务']], ['要同一个事务'])),
]
A = mkartx('x87', 87, 'Spring,Data,JPA,Repository,动态代理,事务,真实验证,动画演示',
    '实测 Spring Data JPA 的 Repository 接口为什么不用写实现:容器里是 JDK 动态代理 $Proxy107,Bean 定义是 JpaRepositoryFactoryBean,目标对象是 SimpleJpaRepository,代理上挂了 7 个拦截器;findAll/findById/count 在只读事务里,save 在可写事务里,派生查询与自定义片段没有事务。',
    'UserRepo 只是个接口,运行时是谁在干活?一次 findAll 经过了哪些拦截器?事务是从哪来的?为什么派生查询没有事务?这篇在 Spring Boot 4.0.8、Hibernate 7、MySQL 上把代理拆开看。',
    [('$Proxy107', '容器里的 UserRepo 是 JDK 动态代理,目标是 SimpleJpaRepository'), ('7 个', '代理上挂着的拦截器个数,事务拦截器排第 3'), ('只读 / 可写 / 没有', 'findAll 在只读事务,save 在可写事务,派生查询没有事务')],
    [('Bean 的真身', '<p>JDK 动态代理,工厂 Bean 是 JpaRepositoryFactoryBean,目标是 SimpleJpaRepository。</p>'),
     ('拦截器链', '<p>7 个拦截器,事务拦截器第 3 个,后面分派到查询方法或基础实现。</p>'),
     ('事务从哪来', '<p>来自 SimpleJpaRepository 上的 @Transactional;派生查询和自定义片段没有事务。</p>'),
     ('调用方的事务', '<p>调用方没有事务时,各个 Repository 调用各开各的事务。</p>')],
    steps,
    [ENV_X + '(Hibernate 7、Spring Data JPA 随 spring-boot-starter-data-jpa;MySQL 是本机自己起的 26.7.0 实例,mysql-connector-j 驱动)。一个实体 User、一个 UserRepo(extends JpaRepository,含派生查询、default 方法、自定义片段 UserRepoCustom);SQL 发出时的调用栈与事务状态用 Hibernate 的 StatementInspector 取得(只保留 Spring Data、AOP、事务相关的栈帧并去重);ddl-auto=create',
     '没有验证:@Query、Specification 等其他查询方式的拦截路径(见后面几篇);Spring Data 的 AOT 仓库(Boot 4 的 AOT 生成实现)对代理的影响;CGLIB 代理(proxyTargetClass);多数据源下的多个 Repository 基础包;方法上写 @Transactional 覆盖默认事务属性的情形;@NoRepositoryBean 与自定义基类(repositoryBaseClass)'],
    'Repository 代理')
